<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Finance;
use HardnessMcp\Context\ExecutionContext; use HardnessMcp\Tools\Finance\Domain\FinanceSummaryRepositoryInterface;
final class FinanceSummaryHandler {
    private FinanceSummaryRepositoryInterface $repository; private string $kind;
    public function __construct(string $kind, FinanceSummaryRepositoryInterface $repository){$this->kind=$kind;$this->repository=$repository;}
    /** @return array<string,mixed> */ public function handle(FinanceSummaryInput $input, ExecutionContext $context): array { if($input->getView()==='titles'){$rows=$this->repository->titles($this->kind,$context->getCompanyId(),$input->getDateFrom(),$input->getDateTo(),$input->getStatus(),$input->getPartnerId(),$input->getCarrierId(),$input->getLimit()+1,$input->getDateBasis(),$input->getCursor());$hasMore=count($rows)>$input->getLimit();if($hasMore)$rows=array_slice($rows,0,$input->getLimit());$rows=array_map(static fn(array $row):array=>array_filter($row,static fn($key):bool=>!is_int($key),ARRAY_FILTER_USE_KEY),$rows);$nextCursor=$hasMore&&$rows!==[]?FinanceTitleCursor::encode($rows[count($rows)-1]):null;return ['report'=>$this->kind.'_titles','period'=>['from'=>$input->getDateFrom(),'to'=>$input->getDateTo()],'filters_applied'=>array_filter(['date_basis'=>$input->getDateBasis(),'status'=>$input->getStatus()==='all'?null:$input->getStatus(),'partner_id'=>$input->getPartnerId(),'carrier_id'=>$input->getCarrierId()],static fn($v):bool=>$v!==null),'rows'=>$rows,'has_more'=>$hasMore,'next_cursor'=>$nextCursor];}$summary=$this->repository->summary($this->kind,$context->getCompanyId(),$input->getDateFrom(),$input->getDateTo(),$input->getStatus(),$input->getPartnerId(),$input->getCarrierId(),$input->getDateBasis());$rows=$this->repository->grouped($this->kind,$context->getCompanyId(),$input->getDateFrom(),$input->getDateTo(),$input->getStatus(),$input->getPartnerId(),$input->getCarrierId(),$input->getGroupBy(),$input->getLimit()+1,$input->getDateBasis());$hasMore=in_array($input->getGroupBy(),['partner','carrier'],true)&&count($rows)>$input->getLimit();if($hasMore)$rows=array_slice($rows,0,$input->getLimit());return ['report'=>$this->kind.'_summary','definition'=>$this->kind==='receivable'?'Contas a receber por vencimento: títulos não cancelados e não agrupados.':'Contas a pagar por vencimento: títulos não cancelados.','period'=>['from'=>$input->getDateFrom(),'to'=>$input->getDateTo()],'filters_applied'=>array_filter(['date_basis'=>$input->getDateBasis(),'status'=>$input->getStatus()==='all'?null:$input->getStatus(),'partner_id'=>$input->getPartnerId(),'carrier_id'=>$input->getCarrierId()],static fn($v):bool=>$v!==null),'group_by'=>$input->getGroupBy(),'summary'=>$this->amounts($summary),'rows'=>array_map(fn(array $row):array=>$this->row($row,$input->getGroupBy()),$rows),'has_more'=>$hasMore]; }
    /** @param array<string,mixed> @return array<string,mixed> */ private function amounts(array $row):array{return ['total_amount'=>(string)($row['total_amount']??'0'),'settled_amount'=>(string)($row['settled_amount']??'0'),'open_amount'=>(string)($row['open_amount']??'0'),'overdue_amount'=>(string)($row['overdue_amount']??'0'),'title_count'=>(int)($row['title_count']??0)];}
    /** @param array<string,mixed> @return array<string,mixed> */ private function row(array $row,string $groupBy):array{$key=[];if($groupBy==='day')$key=['date'=>(string)$row['date']];if($groupBy==='month')$key=['month'=>(string)$row['month']];if($groupBy==='partner')$key=['partner_id'=>$row['partner_id']===null?null:(int)$row['partner_id'],'partner_name'=>$row['partner_name']===null?null:(string)$row['partner_name']];if($groupBy==='carrier')$key=['carrier_id'=>$row['carrier_id']===null?null:(int)$row['carrier_id'],'carrier_name'=>$row['carrier_name']===null?null:(string)$row['carrier_name']];if($groupBy==='origin'||$groupBy==='status')$key=[$groupBy=>(string)$row[$groupBy]];return array_merge($key,$this->amounts($row));}
}
